import { Context, createContext } from 'react';

export type ChipGroupContextProps = {
  /** The number of currently visible chips.
   * @deprecated Please use the visibleKeys instead.
   * */
  visible: number;
  /** The number of currently hidden chips.
   * @deprecated Please use the hiddenKeys instead.
   * */
  hidden: number;
  /** The keys of currently visible chips. */
  visibleKeys: string[];
  /** The keys of currently hidden chips. */
  hiddenKeys: string[];
};

/** The `ChipGroupContext` provides access to the number of currently visible / hidden chips. */
export const ChipGroupContext: Context<ChipGroupContextProps> =
  createContext<ChipGroupContextProps>({
    hiddenKeys: [],
    visibleKeys: [],
    visible: 0,
    hidden: 0,
  });
